sql_query:
SELECT COUNT(*) AS dot_balls
FROM history2.fixtures__balls b
WHERE b.fixture_id = 9998 AND b.bowler__fullname = 'Sam Curran' AND b.score__runs = 0;

SELECT COUNT(*) AS dot_balls
FROM history2.fixtures__balls b
WHERE b.fixture_id = 9998 AND b.bowler__fullname = 'Murugan Ashwin' AND b.score__runs = 0;
